      { id: 12, question: "Why should you never use CSS 'outline: none' on links without a replacement?", options: [{ id: "a", text: "It breaks hover effects on all modern browsers", correct: false }, { id: "b", text: "It removes the visible keyboard focus indicator, making navigation impossible for keyboard-only users", correct: true }, { id: "c", text: "It causes the link to open in a new tab unexpectedly", correct: false }, { id: "d", text: "It prevents the href attribute from functioning correctly", correct: false }] }
